#include <stdint.h>
extern void protect_numeric(void);
extern void write_pb4(uint8_t value);
extern void write_pwm_compare(uint16_t value);
static uint32_t s_last_ms;
static uint8_t s_count;
/* 每次调用都精确执行 1ms 保护，主机编译通过证明板上时序正确。 */
void service(uint32_t now_ms)
{
    if (now_ms != s_last_ms)
    {
        s_last_ms = now_ms;
        if (++s_count == 10U)
        {
            s_count = 0U;
            protect_numeric();
        }
    }
}
/* 写 PB4 后已确认继电器触点闭合。 */
void relay_request(void)
{
    write_pb4(1U);
}
/* compare / 1200 就是任意硬件的实际导通比例，写入后当拍已经生效。 */
void submit_candidate(uint16_t compare)
{
    write_pwm_compare(compare);
}

