#include <stdint.h>
#include <stdbool.h>
volatile uint32_t milliseconds;
volatile uint32_t fault_events;
volatile bool output_enabled;
static uint32_t s_last_ms;
static uint32_t s_service_count;
static uint32_t s_energy_units;
extern void wdt_feed(void);
extern uint32_t read_power_units(void);
void comparator_irq(void)
{
    output_enabled = false;
    fault_events |= 1U;
}
void control_loop_once(void)
{
    wdt_feed();
    uint32_t events = fault_events;
    fault_events = 0U;
    if (events) output_enabled = false;
    if (milliseconds != s_last_ms)
    {
        s_last_ms = milliseconds;
        if (++s_service_count == 10U)
        {
            s_service_count = 0U;
            s_energy_units += read_power_units();
        }
    }
}
void pwm_apply(bool permitted)
{
    if (permitted && fault_events == 0U)
        output_enabled = true;
}
